#include "studio_legacy_media.h"
#include "studio_palette.h"
#include <filesystem>
#include <fstream>
#include <chrono>
#include <iostream>
using Bytes=std::vector<unsigned char>;
static int failures=0;
#define CHECK(x) do{if(!(x)){std::cerr<<"FAIL "<<__LINE__<<": " #x " / "<<error<<"\n";++failures;}}while(0)
static void word(Bytes &b,unsigned n){b.push_back((unsigned char)(n>>8));b.push_back((unsigned char)n);}
static void dword(Bytes &b,unsigned n){for(int i=24;i>=0;i-=8)b.push_back((unsigned char)(n>>i));}
static void chunk(Bytes &b,const char *tag,const Bytes &v){b.insert(b.end(),tag,tag+4);dword(b,(unsigned)v.size());b.insert(b.end(),v.begin(),v.end());if(v.size()&1)b.push_back(0);}
static Bytes dest(int depth,unsigned pick,unsigned on,unsigned mask){Bytes b={(unsigned char)depth,0};word(b,pick);word(b,on);word(b,mask);return b;}
static Bytes fixture(Bytes destination,bool rle=false,int masking=0,int planes=2,int palette=16,unsigned mode=0,bool packed=false){
    Bytes b={'F','O','R','M',0,0,0,0};const char *tag=packed?"PBM ":"ILBM";b.insert(b.end(),tag,tag+4);Bytes h;word(h,9);word(h,2);word(h,0);word(h,0);h.insert(h.end(),{(unsigned char)planes,(unsigned char)masking,(unsigned char)rle,0});word(h,2);h.insert(h.end(),{1,1});word(h,9);word(h,2);chunk(b,"BMHD",h);Bytes colors;for(int i=0;i<palette;++i){colors.push_back((unsigned char)((i&31)*8));colors.push_back((unsigned char)(((i*3)&31)*8));colors.push_back((unsigned char)(((i*7)&31)*8));}chunk(b,"CMAP",colors);chunk(b,"DEST",destination);Bytes camg;dword(camg,mode);chunk(b,"CAMG",camg);chunk(b,"GRAB",{255,249,0,13});Bytes body;
    for(int y=0;y<2;++y)for(int p=0;p<planes+(masking==1);++p){Bytes scan(2);for(int x=0;x<9;++x){int index=(x+y)% (1<<planes);bool on=p==planes?(x+y)%3!=0:((index>>p)&1)!=0;if(on)scan[x/8]|=(unsigned char)(128>>(x&7));}if(rle){body.push_back(128);body.push_back(1);}body.insert(body.end(),scan.begin(),scan.end());}chunk(b,"BODY",body);unsigned n=(unsigned)b.size()-8;for(int i=0;i<4;++i)b[4+i]=(unsigned char)(n>>(24-i*8));return b;
}
static Bytes read(const std::filesystem::path &p){std::ifstream f(p,std::ios::binary);return {std::istreambuf_iterator<char>(f),{}};}
int main(){using namespace studio;namespace fs=std::filesystem;std::string error;IndexedMedia m;auto input=fixture(dest(4,10,5,15));CHECK(decode_indexed_media(input,LegacyMediaKind::Lbm,m,error));CHECK(m.w==9&&m.h==2&&m.words.size()==16&&m.anchor_x==-7&&m.anchor_y==13&&m.note.find("DEST remapped 2 source planes into 4")!=std::string::npos);if(m.pixels.size()!=18)return 1;const unsigned mapped[]={5,7,13,15};for(int y=0;y<2;++y)for(int x=0;x<9;++x)CHECK(m.pixels[y*9+x]==mapped[(x+y)%4]);auto original=m;
    for(bool rle:{false,true}){CHECK(decode_indexed_media(fixture(dest(4,0xfffa,0xfff5,0xffff),rle),LegacyMediaKind::Lbm,m,error)&&m.pixels==original.pixels&&m.words==original.words);CHECK(decode_indexed_media(fixture(dest(4,10,15,15),rle),LegacyMediaKind::Lbm,m,error)&&m.pixels==original.pixels);for(int mask:{1,2}){CHECK(decode_indexed_media(fixture(dest(4,10,5,15),rle,mask),LegacyMediaKind::Lbm,m,error));for(int y=0;y<2;++y)for(int x=0;x<9;++x){int index=(x+y)%4;bool visible=mask==1?(x+y)%3!=0:index!=2;CHECK(m.pixels[y*9+x]==(visible?mapped[index]:0));}}}
    // Ordinary source bits can target the EHB select bit; effective depth is
    // the destination depth, not BMHD's number of stored source planes.
    CHECK(decode_indexed_media(fixture(dest(6,0x20,3,63),true,0,1,32,0x80),LegacyMediaKind::Lbm,m,error)&&m.words.size()==64&&m.pixels[0]==3&&m.pixels[1]==35&&m.note.find("DEST remapped 1")!=std::string::npos);CHECK(m.words[35]==(unsigned short)((m.words[3]>>1)&0x3def));
    // DEST can supply every bit as a constant without stored source planes.
    CHECK(decode_indexed_media(fixture(dest(4,0,5,15),false,0,0),LegacyMediaKind::Lbm,m,error));for(auto c:m.pixels)CHECK(c==5);
    CHECK(decode_indexed_media(fixture(dest(4,0,5,15),true,1,0),LegacyMediaKind::Lbm,m,error));for(int y=0;y<2;++y)for(int x=0;x<9;++x)CHECK(m.pixels[y*9+x]==((x+y)%3?5:0));
    // Opaque zero after scattering is preserved by existing mask handling.
    CHECK(decode_indexed_media(fixture(dest(4,10,0,15),false,1),LegacyMediaKind::Lbm,m,error)&&m.note.find("Opaque color zero moved")!=std::string::npos);for(int y=0;y<2;++y)for(int x=0;x<9;++x){int index=(x+y)%4;bool visible=(x+y)%3!=0;unsigned value=((index&1)<<1)|((index&2)<<2);CHECK(visible?m.pixels[y*9+x]!=0&&m.words[m.pixels[y*9+x]]==original.words[value]:m.pixels[y*9+x]==0);}
    auto reject=[&](const Bytes &b){m=original;CHECK(!decode_indexed_media(b,LegacyMediaKind::Lbm,m,error)&&m.pixels==original.pixels&&m.words==original.words);};for(size_t n=0;n<input.size();++n)reject(Bytes(input.begin(),input.begin()+n));for(int depth:{0,9,16,255})reject(fixture(dest(depth,10,5,65535)));reject(fixture(dest(4,1,0,15)));reject(fixture(dest(4,7,0,15)));reject(fixture(dest(4,10,5,7)));CHECK(error.find("background")!=std::string::npos);reject(fixture(dest(4,10,5,15),false,0,8,16,0,true));reject(fixture({4,0,0,10,0,5}));reject(fixture(dest(4,10,5,15),false,0,2,8));reject(fixture(dest(5,3,0,31),false,0,2,32,0x80));reject(fixture(dest(4,10,5,15),false,0,2,16,0x800));
    // Identity mapping and a full 8-bit destination have no special index
    // restrictions. Upper bits and the reserved byte do not alter the output.
    auto identity=dest(2,3,65535,65535);identity[1]=255;CHECK(decode_indexed_media(fixture(identity),LegacyMediaKind::Lbm,m,error));for(int y=0;y<2;++y)for(int x=0;x<9;++x)CHECK(m.pixels[y*9+x]==(x+y)%4);CHECK(decode_indexed_media(fixture(dest(8,255,0,255),true,0,8,256),LegacyMediaKind::Lbm,m,error)&&m.words.size()==256);
    auto root=fs::temp_directory_path()/("studio-iff-dest-"+std::to_string(std::chrono::steady_clock::now().time_since_epoch().count()));fs::create_directories(root);auto art=Artwork::demo();auto source=root/"source.IMG";CHECK(art->save(source.u8string(),error));auto raw=read(source);auto count=art->count(),pals=art->palette_count();auto version=art->disk_version();auto generation=art->generation();ImportBatch batch;CHECK(build_indexed_import(*art,original,"DESTIMPORT",-1,-7,13,batch,error)&&art->generation()==generation&&!art->dirty());CHECK(art->import_batch(batch,error)==count&&copy_palette(*art,pals).words==original.words&&art->copy(count,0,0,9,2).pixels==original.pixels&&art->disk_version()==version);CHECK(art->save((root/"import.IMG").u8string(),error));auto round=Artwork::open((root/"import.IMG").u8string(),error);CHECK(round&&round->disk_version()==version&&copy_palette(*round,pals).words==original.words&&round->copy(count,0,0,9,2).pixels==original.pixels);art->undo();CHECK(art->count()==count&&art->palette_count()==pals);art->redo();CHECK(art->count()==count+1);CHECK(build_indexed_import(*art,original,"MATCHED",0,0,0,batch,error)&&art->import_batch(batch,error)==count+1&&art->palette_count()==pals+1);art->undo();for(auto kind:{LegacyMediaKind::Lbm,LegacyMediaKind::Tga}){Bytes encoded;IndexedMedia decoded;CHECK(encode_indexed_media(original,kind,encoded,error)&&decode_indexed_media(encoded,kind,decoded,error)&&decoded.words==original.words&&decoded.pixels==original.pixels);}CHECK(read(source)==raw);fs::remove_all(root);std::cout<<"IFF DEST: "<<failures<<" failures\n";return failures?1:0;
}
